return [{
  json: {
    topics: ["ai safety", "model context protocol", "n8n automation", "vector databases", "prompt injection"],
    endpoints: {
      stackoverflow: "https://api.stackexchange.com/2.3/search/advanced?order=desc&sort=activity&site=stackoverflow&q=",
      github: "https://api.github.com/search/repositories?q=",
      arxiv: "https://export.arxiv.org/api/query?search_query=all:"
    },
    rss_feeds: [
      "https://hnrss.org/frontpage",
      "https://www.nasa.gov/rss/dyn/breaking_news.rss"
    ],
    config: {
      cache_ttl_minutes: 45,
      dedupe_ttl_days: 10,
      min_score: 5,
      max_items_total: 30,
      enable_llm_summary: true,
      ZAI_API_KEY: $env.ZAI_API_KEY || "",
      ZAI_BASE_URL: $env.ZAI_BASE_URL || "https://api.z.ai/api/paas/v4",
      ZAI_MODEL: $env.ZAI_MODEL || "glm-5"
    }
  }
}];

const items = [];
const data = $input.all();
for (const item of data) {
  const feedUrl = item.json.rss_url;
  const entries = Array.isArray(item.json) ? item.json : (item.json.items || []);
  for (const entry of entries) {
    items.push({
      json: {
        source: "rss",
        topic: null,
        title: entry.title || "Untitled",
        url: entry.link || entry.url || "",
        published_at: entry.pubDate || entry.isoDate || null,
        raw_score: 0,
        score: 5,
        summary_raw: entry.contentSnippet || entry.description || null,
        summary: null,
        meta: { author: entry.creator || null, venue: feedUrl, cached: false }
      }
    });
  }
}
return items.length > 0 ? items : [{ json: { __empty: true, __stream: "rss" } }];

const init = $('Init').first().json;
return [{
  json: {
    topic: $json.topic,
    config: init.config,
    endpoints: init.endpoints
  }
}];

const st = $getWorkflowStaticData('global');
if (!st.seen) st.seen = {};
const now = Date.now();
const config = $('Init').first().json.config;
const ttl = config.dedupe_ttl_days * 24 * 60 * 60 * 1000;

// Prune old entries
for (const url in st.seen) {
  if (now - st.seen[url] > ttl) delete st.seen[url];
}

let candidates = 0;
let newItems = 0;
let cachedHits = 0;
let apiCalls = 0;
let failedCalls = 0;
const bySource = {};
const items = [];

const input = $input.all();
for (const item of input) {
  const i = item.json;
  if (i.__empty) continue;
  candidates++;
  if (!bySource[i.source]) bySource[i.source] = 0;
  bySource[i.source]++;
  if (i.meta && i.meta.cached) cachedHits++;
  if (i.__meta) {
    if (i.__meta.api_calls) apiCalls += i.__meta.api_calls;
    if (i.__meta.failed_calls) failedCalls += i.__meta.failed_calls;
  }

  if (i.score >= config.min_score && i.url && !st.seen[i.url]) {
    st.seen[i.url] = now;
    newItems++;
    items.push(i);
  }
}

items.sort((a, b) => b.score - a.score);
const finalItems = items.slice(0, config.max_items_total);

return [{
  json: {
    config,
    stats: {
      candidates_total: candidates,
      new_items: newItems,
      cached_hits: cachedHits,
      api_calls: apiCalls,
      failed_calls: failedCalls,
      by_source: bySource
    },
    items: finalItems,
    run_id: $execution.id,
    generated_at: new Date().toISOString()
  }
}];

const topItems = $json.items.slice(0, 12).map(i => ({ url: i.url, title: i.title, summary_raw: i.summary_raw || '' }));
const content = `Summarize these items in JSON format {"summaries":[{"url","summary"}]}. Max 20 words per summary.\n` + JSON.stringify(topItems);
return [{
  json: {
    ...$json,
    llm_payload: {
      model: $json.config.ZAI_MODEL,
      messages: [{ role: "user", content }],
      temperature: 0.2,
      response_format: { type: "json_object" }
    }
  }
}];

const prev = $('Prepare LLM').first().json;
let items = prev.items;
const resp = $json;

if (resp?.choices?.[0]?.message?.content) {
  try {
    const parsed = JSON.parse(resp.choices[0].message.content);
    if (parsed.summaries && Array.isArray(parsed.summaries)) {
      const map = new Map(parsed.summaries.map(s => [s.url, s.summary]));
      items = items.map(i => ({ ...i, summary: map.get(i.url) || i.summary_raw || i.title }));
    }
  } catch (e) {
    items = items.map(i => ({ ...i, summary: i.summary_raw || i.title }));
  }
} else {
  items = items.map(i => ({ ...i, summary: i.summary_raw || i.title }));
}

return [{ json: { ...prev, items } }];

const data = $json;
if (!Array.isArray(data.items)) throw new Error('Items must be array');
for (const i of data.items) {
  if (!i.url || typeof i.url !== 'string') throw new Error('Invalid URL');
  if (typeof i.score !== 'number') throw new Error('Invalid score');
  const s = JSON.stringify(i);
  if (s.includes('{{')) throw new Error('Contains mustache');
}
return [{ json: data }];

const data = $json;
const lines = [];
const groups = {};
for (const i of data.items) {
  if (!groups[i.source]) groups[i.source] = [];
  groups[i.source].push(i);
}
for (const [src, items] of Object.entries(groups)) {
  lines.push(`## ${src}`);
  for (const i of items) {
    lines.push(`- [${i.title}](${i.url}) (score ${i.score})`);
  }
}
return [{
  json: {
    run_id: data.run_id,
    generated_at: data.generated_at,
    topics: $('Init').first().json.topics,
    stats: data.stats,
    items: data.items,
    digest_markdown: lines.join('\n')
  }
}];
